  if (signal.aborted)
    throw new CommunicationsError(
      "cancelled",
      "Communications operation cancelled.",
    );
}
/** Cancellation settles promptly even when an optional loader ignores AbortSignal. */
export function withVoiceCancellation<T>(
  pending: Promise<T>,
  signal: AbortSignal,
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    let settled = false;
    function finish(action: () => void) {
      if (settled) return;
      settled = true;
      signal.removeEventListener("abort", aborted);
      action();
    }
    const aborted = () =>
      finish(() =>
        reject(
          new CommunicationsError(
            "cancelled",
            "Communications operation cancelled.",
          ),
        ),
      );
    signal.addEventListener("abort", aborted, { once: true });
    pending.then(
      (value) => {
        if (signal.aborted) aborted();
        else finish(() => resolve(value));
      },
      (error: unknown) => {
        finish(() => reject(error));
      },
    );
