}

export function createLiveCommunicationsAdapter(
  options: LiveCommunicationsAdapterOptions,
): LiveCommunicationsAdapter {
  if (
    !providerSchema.safeParse(options.provider).success ||
    typeof options.baseUrl !== "string"
